const rows = items.map(i => i.json);
const seen = new Set();
const duplicates = [];
const missingIds = [];
const negativeAmounts = [];
let total = 0;
let open = 0;
for (let index = 0; index < rows.length; index++) {
  const r = rows[index];
  const id = String(r.id ?? '').trim();
  const amount = Number(r.amount ?? 0);
  if (!id) missingIds.push(index + 1);
  if (id && seen.has(id)) duplicates.push(id);
  if (id) seen.add(id);
  if (amount < 0) negativeAmounts.push({ row: index + 1, id, amount });
  if (Number.isFinite(amount)) total += amount;
  if (String(r.status).toLowerCase() === 'open') open++;
}
return [{ json: {
  rowCount: rows.length,
  totalAmount: total,
  openCount: open,
  issues: { missingIds, duplicates: [...new Set(duplicates)], negativeAmounts },
  hasIssues: missingIds.length > 0 || duplicates.length > 0 || negativeAmounts.length > 0
} }];

const r = items[0].json;
const issueCount = r.issues.missingIds.length + r.issues.duplicates.length + r.issues.negativeAmounts.length;
const recommendation = r.hasIssues
  ? `Controle nodig vóór rapportage: ${issueCount} dataprobleem/problemen gevonden.`
  : 'Geen blokkerende dataproblemen gevonden; rapportage kan worden vernieuwd.';
return [{ json: {
  status: r.hasIssues ? 'REVIEW' : 'READY',
  recommendation,
  metrics: { rows: r.rowCount, totalAmount: r.totalAmount, openItems: r.openCount },
  issues: r.issues,
  nextStep: r.hasIssues ? 'Corrigeer de gemarkeerde rijen en voer de workflow opnieuw uit.' : 'Publiceer of verzend het periodieke rapport.'
} }];
